  var mon=new Date(today);mon.setDate(mon.getDate()-((mon.getDay()+6)%7));var week=[];for(var i=0;i<7;i++){var dd=new Date(mon);dd.setDate(mon.getDate()+i);week.push({n:dd.getDate(),read:!!days[key(dd)],today:key(dd)===tk})}
