var CH_ICON_KEYS=Object.keys(CH_ICONS);
function chIconSvg(k){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(CH_ICONS[k]||CH_ICONS.cross)+'</svg>'}
function chIconOf(u){return String(u||'').indexOf('icon:')===0?String(u).slice(5).split('|'):null}
var CH_LOGO_HEX=['#F5C12E','#2BA6E8','#9BCB3B','#3C5E70','#E8A33D'];
var CH_BAN_HEX=['#F5C12E','#2BA6E8','#9BCB3B','#3C5E70','#E8A33D'];
var CH_LOGO_DEF={'#F5C12E':'book','#2BA6E8':'dove','#9BCB3B':'olive','#3C5E70':'cross','#E8A33D':'star'};
function chColorOf(u){return String(u||'').indexOf('color:')===0?String(u).slice(6):''}
function chLogoPick(){var cur=CHF.logoColor||'#3C5E70';var row='<div class="chsws">'+CH_LOGO_HEX.map(function(h){var on=cur===h;var k=on?(CHF.logoIcon||CH_LOGO_DEF[h]):CH_LOGO_DEF[h];var inner='<span class="chsvg" style="color:'+chTextOn(h)+'">'+chIconSvg(k)+'</span>';return on?'<button type="button" class="chsw chsww on" data-chiconopen="1" aria-label="'+ck('iconPick')+'" style="background:'+h+'">'+inner+'</button>':'<button type="button" class="chsw chsww" data-chpreset="logo" data-hex="'+h+'" data-icon="'+CH_LOGO_DEF[h]+'" style="background:'+h+'" aria-label="'+h+'">'+inner+'</button>'}).join('')+'</div>';var k2=CHF.logoIcon||CH_LOGO_DEF[cur]||'cross';var grid=CHF.iconOpen?'<div class="chicons">'+CH_ICON_KEYS.map(function(x){return '<button type="button" class="chic'+(k2===x?' on':'')+'" data-chicon="'+x+'" aria-label="'+x+'">'+chIconSvg(x)+'</button>'}).join('')+'</div>':'';return row+grid}
function chSwatches(kind){var hexes=kind==='logo'?CH_LOGO_HEX:CH_BAN_HEX;var cur=CHF[kind+'Color']||'';return '<div class="chsws">'+hexes.map(function(h){return '<button type="button" class="chsw'+(cur===h?' on':'')+'" data-chpreset="'+kind+'" data-hex="'+h+'" style="background:'+h+'" aria-label="'+h+'"></button>'}).join('')+'</div>'}
function chBanner(c){var col=chColorOf(c.banner_url);if(col)return '<div class="chban" style="background:'+esc(col)+'"></div>';if(c.banner_url)return '<img class="chban" src="'+esc(c.banner_url)+'" alt="">';return '<div class="chban chban0"></div>'}
function chTextOn(h){var r=parseInt(h.slice(1,3),16),g=parseInt(h.slice(3,5),16),b=parseInt(h.slice(5,7),16);return (0.299*r+0.587*g+0.114*b)>150?'#1d2b33':'#fff'}
function chLogo(c,cls){var ic=chIconOf(c.logo_url);if(ic){var ih=ic[1]||'#3C5E70';return '<span class="'+cls+' chfb" style="background:'+esc(ih)+';color:'+chTextOn(ih)+'">'+chIconSvg(ic[0])+'</span>'}var col=chColorOf(c.logo_url);if(col)return '<span class="'+cls+' chfb" style="background:'+esc(col)+';color:'+chTextOn(col)+'">'+esc(String(c.name||'?').charAt(0).toUpperCase())+'</span>';return c.logo_url?'<img class="'+cls+'" src="'+esc(c.logo_url)+'" alt="">':'<span class="'+cls+' chfb">'+esc(String(c.name||'?').charAt(0).toUpperCase())+'</span>'}
function chTag(c,sp){var sn=sp?(SUBS.find(function(z){return z.id===sp})||{}).name:'';return '<span class="chtag" data-chopen="'+c.id+'">'+chLogo(c,'chlogo')+'<span>'+esc(c.name)+(sn?' › '+esc(sn):'')+'</span></span>'}
function jbUserId(){if(!D)return null;for(var u in D.un){if(D.un[u]&&D.un[u].toLowerCase().indexOf('jesusbootcamp')>=0)return u}for(var u in D.nm){if(D.nm[u]&&D.nm[u].toLowerCase().indexOf('jesus bootcamp')>=0)return u}return null}
function chOwnerName(c){if(c&&c.name&&c.name.trim().toLowerCase()==='jesus bootcamp')return 'Jesus Bootcamp';return who(c.owner_id)}
function loadAdmins(){api('bible_channel_admins?select=channel_id,user_id&limit=2000').then(function(r){var m={};(Array.isArray(r)?r:[]).forEach(function(x){(m[x.channel_id]=m[x.channel_id]||new Set()).add(x.user_id)});CHADM=m;render()}).catch(function(){})}
function chIsAdm(cid){return !!(D&&CHADM[cid]&&CHADM[cid].has(D.self))}
function chMgr(cid){var c=chById(cid);return !!(D&&!ANON&&(D.admin||(c&&c.owner_id===D.self)||chIsAdm(cid)))}
function loadChannels(){CHL=1;loadAdmins();loadSubs();api('bible_channels?select=*&order=created_at.desc&limit=300').then(function(r){CH=(Array.isArray(r)?r:[]).map(function(c){if(c&&c.name&&c.name.trim().toLowerCase()==='jesus bootcamp'){var jb=jbUserId();if(jb)c.owner_id=jb}return c});render()}).catch(function(){CH=[];render()})}
function chNewLink(){return ANON?'':'<div style="margin:8px 0 4px"><a class="fb" href="#feed/newchannel" style="display:inline-block;text-decoration:none">'+ck('newch')+'</a></div>'}
function chanBlock(){var h='<div class="sh" style="margin-top:22px"><h2>'+ck('chans')+'</h2><a class="more" href="#feed/channels">'+ck('allch')+' ›</a></div>';var plus=ANON?'':'<a class="chcard chplus" href="#feed/newchannel"><span class="chplusc"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></span><b>'+ck('makeCh')+'</b></a>';if(!CH.length)return h+'<div class="chrow">'+plus+'</div><div class="empty" style="padding:10px 0">'+ck('nochan')+'</div>';return h+'<div class="chrow">'+plus+CH.slice(0,12).map(function(c){return '<a class="chcard" href="#feed/channel/'+c.id+'">'+chLogo(c,'chlogo')+'<b>'+esc(c.name)+'</b><small>'+chVisLabel(c.visibility)+'</small><span class="fb on chview">'+ck('viewCh')+'</span></a>'}).join('')+'</div>'}
function chListRow(c){return '<div class="chrow1"><a class="chlink" href="#feed/channel/'+c.id+'">'+chLogo(c,'chlogo')+'<div><b>'+esc(c.name)+'</b>'+(c.description?'<small>'+esc(chPlain(c.description))+'</small>':'')+'<small>'+chVisLabel(c.visibility)+'</small><small>'+chCount(c.id)+' '+(CKT[L==='en'?'en':'nl'].chmsgs)+'</small></div></a>'+chJoinBtn(c,'fb')+'</div>'}
function pageChannels(){return sub(ck('chans'))+chNewLink()+(CH.length?'<div class="chlist">'+CH.map(chListRow).join('')+'</div>':'<div class="empty">'+ck('nochan')+'</div>')}
/* Websites in een kanaalbeschrijving zijn klikbaar: https://..., www.... of een kale domeinnaam (.nl, .com, .org, ...). E-mailadressen blijven tekst. */
function chLinks(t){return chLinkify(esc(t))}
function chRich(t){return chLinkify(fmtText(t))}
function chPlain(t){var x=String(t||'').replace(/\*\*|__/g,'').replace(/\*([^*\n]+?)\*/g,'$1').replace(/\s+/g,' ').trim();return x.length>140?x.slice(0,140)+'…':x}
function chLinkify(h){return h.replace(/(^|[\s(>])((?:https?:\/\/)?(?:www\.)?[a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)*\.(?:nl|com|org|net|eu|be|de|io|co|app|info|tv|me|nu|dev|uk|fr|es|ch|at|church|online|site|world)(?:\/[^\s<]*)?)/gi,function(m,pre,u){var tail='';var mt=u.match(/[.,;:!?)]+$/);if(mt){tail=mt[0];u=u.slice(0,-tail.length)}if(!u)return m;var href=/^https?:\/\//i.test(u)?u:'https://'+u;return pre+'<a href="'+href+'" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:underline;word-break:break-all">'+u+'</a>'+tail})}
/* Livekaart hoort bij het eigen kanaal (niet bovenaan Gemeenschap): Jesus Bootcamp -> 'jb', De Samenkomst -> 'samenkomst' */
