function onLiveChange(){if(root&&!SHEET)render()}
function liveHtml(only){
  var list=(window.__onkLive||[]).filter(function(x){return !only||x.key===only});
  if(!list.length)return '';
  var en=L==='en',rt=window.__onkRoot||'/',out='';
  list.forEach(function(x){
    var test=window.__onkLiveTest?'<span class="lv-test">TEST</span>':'';
    var badge='<span class="lv-badge"><i></i>'+(en?'Live now':'Nu live')+'</span>';
    if(x.key==='samenkomst'){
      out+='<a class="lv-card lv-sk" href="'+esc(x.url)+'" target="_blank" rel="noopener"><div class="lv-logo"><img alt="" src="'+esc(rt+'img/brand/de-samenkomst-profiel-2.png')+'"></div>'+badge+'<div class="lv-kind">Live meeting</div><h3>'+(en?'De Samenkomst is live':'De Samenkomst is live')+'</h3><span class="lv-btn">'+(en?'Join the meeting':'Doe mee aan de meeting')+'</span>'+test+'</a>';
    }else if(x.videoId){
      /* Echte livestream: de speler staat direct onder de titel (ingebed), geen extra knop. */
      out+='<div class="lv-card"><span class="lv-badge"><i></i>'+(en?'Live now':'Nu live')+'</span><div class="lv-kind">Livestream</div><h3>'+esc(x.title||'Jesus Bootcamp')+'</h3><div class="lv-emb"><iframe src="https://www.youtube.com/embed/'+esc(x.videoId)+'?rel=0" title="'+esc(x.title||'Jesus Bootcamp')+'" allow="accelerometer; autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen loading="lazy"></iframe></div>'+test+'</div>';
    }else{
      out+='<a class="lv-card" href="'+esc(x.url)+'" target="_blank" rel="noopener">'+(x.thumb?'<div class="lv-thumb" style="background-image:url(&quot;'+esc(x.thumb)+'&quot;)">'+badge+'</div>':badge)+'<div class="lv-kind">Livestream</div><h3>'+esc(x.title||'Jesus Bootcamp')+'</h3><span class="lv-btn">'+(en?'Watch the livestream':'Bekijk de livestream')+'</span>'+test+'</a>';
    }
  });
  return '<div class="lv-wrap">'+out+'</div>';
}
